// BUILD: Manager Approval Form
// Fetches the specific leave request by ID, enriches with employee data, builds HTML

const allRequests = $('Get Request (Manager Form)').all().map(i => i.json);
const allEmployees = $('Get Employee (Manager Form)').all().map(i => i.json);

const params = $input.first().json.query || {};
const requestId = params.requestId || '';

const req = allRequests.find(r => String(r.RequestID || '').trim() === String(requestId).trim());
if (!req) throw new Error('Request not found: ' + requestId);

const emp = allEmployees.find(e => String(e.EmployeeID || '').trim() === String(req.EmployeeID || '').trim());
if (!emp) throw new Error('Employee not found for request');

const data = {
  RequestID: req.RequestID,
  RequestDate: req.RequestDate || '',
  EmployeeID: req.EmployeeID,
  EmployeeName: emp.FullName || '',
  EmployeeEmail: emp.Email || '',
  Role: emp.Role || '',
  Department: emp.Department || '',
  Branch: emp.Branch || emp.Department || '',
  ManagerName: emp['Manager Name'] || emp.ManagerName || '',
  ManagerEmail: emp.ManagerEmail || '',
  LeaveType: req.LeaveType || '',
  StartDate: req.StartDate || '',
  EndDate: req.EndDate || '',
  ResumptionDate: req.ResumptionDate || '',
  NumberOfDays: req.NumberOfDays || '',
  DaysPreviousTaken: req.DaysPreviousTaken || '0',
  Reliever: req.Reliever || '',
  ContactAddress: req.ContactAddress || '',
  PhoneNumber: req.PhoneNumber || '',
  LeaveBalance: emp.LeaveBalance || '0',
  TotalLeaveDays: emp.TotalLeaveDays || '0',
  ManagerStatus: req.ManagerStatus || 'Pending',
  ManagerComment: req.ManagerComment || '',
  ManagerDecisionDate: req.ManagerDecisionDate || ''
};

const encoded = Buffer.from(JSON.stringify(data)).toString('base64');

const policyMap = {
  'Annual Leave': 'Annual leave deducts from table_2 Policy: min 2 weeks notice, recommended March–October.',
  'Sick Leave': 'Employee must submit medical certificate within 24 hours. Balance not deducted.',
  'Casual Leave': 'Max 3 days/year. Only after annual leave exhausted.',
  'Compassionate Leave': 'Max 5 working days/year. Subject to management discretion.',
  'Maternity Leave': '12 weeks. Medical cert at least 1 month in advance. Min 6 months service required.',
  'Paternity Leave': '5 working days. Does not affect annual leave balance.',
  'Leave of Absence': 'Unpaid. Final approval at management discretion.',
  'Examination Leave': 'Max 5 working days. Employee should use annual leave where possible.'
};

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>Leave Approval — Orange Group</title>
<link href="[URL]" rel="stylesheet">
<style>
:root{--orange:#E85D04;--orange-dark:#C44B00;--orange-light:#FFF3ED;--orange-mid:#FFD6B8;
--black:#1A1008;--grey-dark:#3D3028;--grey-mid:#8A7A6E;--grey-light:#F5F0EB;
--white:#FFFFFF;--border:#E8DDD5;--success:#2D6A4F;--success-light:#EDFAF3;
--error:#C1121F;--error-light:#FFF0F0;--shadow-lg:0 12px 48px rgba(232,93,4,0.16)}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{font-family:'DM Sans',sans-serif;background:var(--grey-light);min-height:100vh;
display:flex;flex-direction:column;align-items:center;padding:40px 16px 80px}
.logo-wrap{margin-bottom:28px}
.logo-badge{background:var(--orange);border:2px solid var(--orange-dark);display:inline-flex;
align-items:center;gap:10px;padding:10px 28px;position:relative}
.logo-badge::before{content:'';position:absolute;inset:3px;border:1px solid rgba(255,255,255,0.3)}
.logo-icon{display:flex;gap:4px}
