.logo-text{font-family:'Playfair Display',serif;color:white;font-size:18px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.mgr-badge{background:var(--white);border:1px solid var(--border);padding:8px 20px;font-size:12px;
color:var(--grey-mid);margin-bottom:20px;display:flex;align-items:center;gap:8px;letter-spacing:.06em;text-transform:uppercase}
.mgr-badge strong{color:var(--black);font-size:14px;text-transform:none;letter-spacing:0}
.card{background:var(--white);width:100%;max-width:620px;border-radius:2px;box-shadow:var(--shadow-lg);overflow:hidden}
