.btn-reject:hover{background:#9B0E1A;transform:translateY(-1px)}
.btn:disabled{background:var(--grey-mid);cursor:not-allowed;transform:none}
.alert{padding:12px 16px;font-size:13px;font-weight:500;margin-bottom:16px;display:none;align-items:center;gap:10px}
.alert.show{display:flex}
.alert.error{background:var(--error-light);color:var(--error);border-left:3px solid var(--error)}
.success-state{padding:48px 36px;text-align:center;display:none}
.success-state.active{display:block}
.s-icon{font-size:52px;margin-bottom:16px}
.success-state h3{font-family:'Playfair Display',serif;font-size:20px;color:var(--black);margin-bottom:8px}
.success-state p{color:var(--grey-mid);font-size:14px;line-height:1.6;max-width:400px;margin:0 auto}
.footer-note{font-size:11px;color:var(--grey-mid);text-align:center;margin-top:28px;letter-spacing:.03em}
.spinner{width:16px;height:16px;border:2px solid rgba(255,255,255,0.4);border-top-color:white;
border-radius:50%;animation:spin .8s linear infinite;display:inline-block;vertical-align:middle;margin-right:6px}
@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:520px){.card-body{padding:24px 20px}.detail-grid,.decision-opts{grid-template-columns:1fr}
.card-header{padding:20px 24px;flex-direction:column;gap:12px}}
</style>
</head>
<body>
<div class="logo-wrap">
  <div class="logo-badge">
    <div class="logo-icon"><div class="logo-dot"></div><div class="logo-dot"></div></div>
    <div class="logo-text">Orange Group</div>
  </div>
</div>
<div class="mgr-badge">👤 Manager Review Portal &nbsp;·&nbsp; <strong id="mgrName">Loading…</strong></div>
<div class="card">
  <div class="card-header">
    <div><h1>Leave Approval</h1><p>Review and action the request below</p></div>
    <div class="hdr-badge">Awaiting Decision</div>
  </div>
  <div class="card-body" id="cardBody">
    <div class="req-strip">
      <div><div class="rid-lbl">Request ID</div><div class="rid-val" id="d_rid">—</div></div>
      <div class="req-date" id="d_rdate">—</div>
    </div>
    <div class="section-label">Employee</div>
    <div class="emp-profile">
      <div class="emp-avatar" id="d_avatar">—</div>
      <div class="emp-info">
        <h3 id="d_name">—</h3><p id="d_email">—</p>
        <div class="emp-tags"><span class="emp-tag" id="d_role">—</span><span class="emp-tag" id="d_dept">—</span></div>
      </div>
    </div>
    <div class="section-label">Leave Details</div>
    <div class="detail-grid">
      <div class="detail-item full"><div class="di-label">Type of Leave</div><div class="di-value"><span class="leave-chip" id="d_type">—</span></div></div>
      <div class="detail-item"><div class="di-label">Start Date</div><div class="di-value" id="d_start">—</div></div>
      <div class="detail-item"><div class="di-label">End Date</div><div class="di-value" id="d_end">—</div></div>
      <div class="detail-item"><div class="di-label">Resumption Date</div><div class="di-value" id="d_res">—</div></div>
      <div class="detail-item"><div class="di-label">Reliever</div><div class="di-value" id="d_rel">—</div></div>
      <div class="detail-item full"><div class="di-label">Contact During Leave</div><div class="di-value" id="d_addr">—</div></div>
      <div class="detail-item"><div class="di-label">Phone</div><div class="di-value" id="d_phone">—</div></div>
      <div class="detail-item"><div class="di-label">Days Previously Taken</div><div class="di-value" id="d_prev">—</div></div>
    </div>
    <div class="days-block">
      <div><div class="db-label">Leave Period</div><div class="db-period" id="d_period">—</div></div>
      <div style="text-align:right"><div class="big-days" id="d_days">—</div><div class="db-sub">working days</div></div>
    </div>
    <div class="balance-row na" id="d_balRow">
      <span class="bal-label">Leave Balance</span><span class="bal-val" id="d_bal">—</span>
    </div>
    <div class="policy-box" id="d_policy"></div>
    <div class="already-decided" id="alreadyDecided"></div>
    <div id="decisionSection">
      <div class="section-label">Your Decision</div>
      <div class="decision-opts">
        <button class="d-btn approve" onclick="selectDecision('approve',this)">
          <div class="d-icon">✅</div><span class="d-label">Approve</span><span class="d-sub">Forward to HR for final sign-off</span>
        </button>
        <button class="d-btn reject" onclick="selectDecision('reject',this)">
          <div class="d-icon">❌</div><span class="d-label">Reject</span><span class="d-sub">Notify employee of rejection</span>
        </button>
      </div>
      <div class="comment-area">
        <label>Comments <span style="color:var(--grey-mid);font-weight:400;text-transform:none;letter-spacing:0">(optional but recommended)</span></label>
        <textarea id="f_comment" placeholder="Add context, conditions, or notes for the employee and HR…"></textarea>
      </div>
      <div class="alert error" id="submitError"><span>⚠</span><span id="submitErrorMsg">Something went wrong.</span></div>
      <button class="btn btn-approve" id="submitBtn" onclick="submitDecision()" disabled>Submit Decision</button>
    </div>
  </div>
  <div class="success-state" id="successState">
    <div class="s-icon" id="s_icon">✅</div>
    <h3 id="s_heading">Decision Submitted</h3>
    <p id="s_msg">Your decision has been recorded and all relevant parties notified.</p>
  </div>
</div>
<div class="footer-note">Orange Group Leave Management System · Manager Portal · Confidential</div>
<script>
const D = JSON.parse(atob('${encoded}'));
const N8N_BASE = '[URL]';
const policyMap = ${JSON.stringify(policyMap)};
let selectedDecision = null;

function fmtDate(s){try{return new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});}catch{return s||'—';}}

function init(){
  document.getElementById('mgrName').textContent = D.ManagerName || 'Manager';
  document.getElementById('d_rid').textContent = D.RequestID;
  document.getElementById('d_rdate').textContent = fmtDate(D.RequestDate);
  const initials = (D.EmployeeName||'??').split(' ').map(n=>n[0]).join('').slice(0,2).toUpperCase();
  document.getElementById('d_avatar').textContent = initials;
  document.getElementById('d_name').textContent = D.EmployeeName||'—';
  document.getElementById('d_email').textContent = D.EmployeeEmail||'—';
  document.getElementById('d_role').textContent = D.Role||'—';
  document.getElementById('d_dept').textContent = D.Department||'—';
  document.getElementById('d_type').textContent = D.LeaveType||'—';
  document.getElementById('d_start').textContent = fmtDate(D.StartDate);
  document.getElementById('d_end').textContent = fmtDate(D.EndDate);
  document.getElementById('d_res').textContent = fmtDate(D.ResumptionDate);
  document.getElementById('d_rel').textContent = D.Reliever||'—';
  document.getElementById('d_addr').textContent = D.ContactAddress||'—';
  document.getElementById('d_phone').textContent = D.PhoneNumber||'—';
  document.getElementById('d_prev').textContent = D.DaysPreviousTaken||'0';
  document.getElementById('d_period').textContent = fmtDate(D.StartDate)+' → '+fmtDate(D.EndDate);
  document.getElementById('d_days').textContent = D.NumberOfDays||'—';
  const bal = parseFloat(D.LeaveBalance)||0;
  const req = parseInt(D.NumberOfDays)||0;
  const balRow = document.getElementById('d_balRow');
  const balVal = document.getElementById('d_bal');
  if(D.LeaveType==='Annual Leave'){
    balVal.textContent = bal+' days remaining';
    if(req>bal){balRow.className='balance-row warn';balVal.textContent='⚠ Only '+bal+' days remaining — '+req+' requested';}
    else balRow.className='balance-row ok';
  } else {
    balRow.className='balance-row na';
    balVal.textContent='N/A — not deducted for '+D.LeaveType;
  }
  const pol = document.getElementById('d_policy');
  pol.textContent = policyMap[D.LeaveType] ? '📋 Policy: '+policyMap[D.LeaveType] : '';
  if(D.ManagerStatus && D.ManagerStatus!=='Pending'){
    const ad = document.getElementById('alreadyDecided');
    ad.style.display='block';
    ad.textContent='This request was already '+D.ManagerStatus.toLowerCase()+' on '+fmtDate(D.ManagerDecisionDate)+'.';
    ad.className='already-decided '+(D.ManagerStatus==='Approved'?'approved':'rejected');
    document.getElementById('decisionSection').style.display='none';
  }
}

function selectDecision(dec, btn){
  selectedDecision=dec;
  document.querySelectorAll('.d-btn').forEach(b=>b.classList.remove('selected'));
  btn.classList.add('selected');
  const sb=document.getElementById('submitBtn');
  sb.disabled=false;
  if(dec==='approve'){sb.className='btn btn-approve';sb.textContent='✅ Approve & Forward to HR';}
  else{sb.className='btn btn-reject';sb.textContent='❌ Reject & Notify Employee';}
}

async function submitDecision(){
  if(!selectedDecision) return;
  const btn=document.getElementById('submitBtn');
  btn.disabled=true;
  btn.innerHTML='<span class="spinner"></span>Submitting…';
  document.getElementById('submitError').classList.remove('show');
  try{
    const res = await fetch(N8N_BASE+'/submit-manager-decision',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({requestId:D.RequestID,decision:selectedDecision,
        comment:document.getElementById('f_comment').value.trim(),
        managerName:D.ManagerName,managerEmail:D.ManagerEmail})
    });
    if(!res.ok) throw new Error('Server error');
    const isApprove=selectedDecision==='approve';
    document.getElementById('s_icon').textContent=isApprove?'✅':'❌';
    document.getElementById('s_heading').textContent=isApprove?'Request Approved':'Request Rejected';
    document.getElementById('s_msg').textContent=isApprove
      ?'Forwarded to HR for final approval. Employee will be notified once HR completes their review.'
      :'Employee has been notified of your decision.';
    document.getElementById('cardBody').style.display='none';
    document.getElementById('successState').classList.add('active');
  }catch(err){
    document.getElementById('submitError').classList.add('show');
    document.getElementById('submitErrorMsg').textContent='Submission failed. Please try again or contact IT.';
    btn.disabled=false;
    btn.textContent=selectedDecision==='approve'?'✅ Approve & Forward to HR':'❌ Reject & Notify Employee';
  }
}

init();
</script>
</body>
</html>`;

return [{ json: { html } }];

// BUILD: HR Final Approval Form

const allRequests = $('Get Request (HR Form)').all().map(i => i.json);
const allEmployees = $('Get Employee (HR Form)').all().map(i => i.json);

const params = $input.first().json.query || {};
const requestId = params.requestId || '';

const req = allRequests.find(r => String(r.RequestID || '').trim() === String(requestId).trim());
if (!req) throw new Error('Request not found: ' + requestId);
if (req.ManagerStatus !== 'Approved') throw new Error('This request has not yet been approved by the manager.');

const emp = allEmployees.find(e => String(e.EmployeeID || '').trim() === String(req.EmployeeID || '').trim());
if (!emp) throw new Error('Employee not found for request');

const data = {
  RequestID: req.RequestID,
  RequestDate: req.RequestDate || '',
  EmployeeID: req.EmployeeID,
  EmployeeName: emp.FullName || '',
  EmployeeEmail: emp.Email || '',
  Role: emp.Role || '',
  Department: emp.Department || '',
  ManagerName: emp['Manager Name'] || emp.ManagerName || '',
  ManagerEmail: emp.ManagerEmail || '',
  LeaveType: req.LeaveType || '',
  StartDate: req.StartDate || '',
  EndDate: req.EndDate || '',
  ResumptionDate: req.ResumptionDate || '',
  NumberOfDays: req.NumberOfDays || '',
  DaysPreviousTaken: req.DaysPreviousTaken || '0',
  Reliever: req.Reliever || '',
  ContactAddress: req.ContactAddress || '',
  PhoneNumber: req.PhoneNumber || '',
  LeaveBalance: emp.LeaveBalance || '0',
  TotalLeaveDays: emp.TotalLeaveDays || '0',
  ManagerStatus: req.ManagerStatus || '',
  ManagerComment: req.ManagerComment || '',
  ManagerDecisionDate: req.ManagerDecisionDate || '',
  HRStatus: req.HRStatus || 'Pending',
  HRComment: req.HRComment || '',
  HRDecisionDate: req.HRDecisionDate || ''
};

const encoded = Buffer.from(JSON.stringify(data)).toString('base64');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>HR Final Approval — Orange Group</title>
<link href="[URL]" rel="stylesheet">
<style>
:root{--orange:#E85D04;--orange-dark:#C44B00;--orange-light:#FFF3ED;--orange-mid:#FFD6B8;
--black:#1A1008;--grey-dark:#3D3028;--grey-mid:#8A7A6E;--grey-light:#F5F0EB;
--white:#FFFFFF;--border:#E8DDD5;--success:#2D6A4F;--success-light:#EDFAF3;
--error:#C1121F;--error-light:#FFF0F0;--hr:#4A1259;--hr-light:#F5EDF9;--hr-mid:#DEC5E8;
--shadow-lg:0 12px 48px rgba(74,18,89,0.16)}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
body{font-family:'DM Sans',sans-serif;background:var(--grey-light);min-height:100vh;
display:flex;flex-direction:column;align-items:center;padding:40px 16px 80px}
.logo-wrap{margin-bottom:24px}
.logo-badge{background:var(--orange);border:2px solid var(--orange-dark);display:inline-flex;
align-items:center;gap:10px;padding:10px 28px;position:relative}
.logo-badge::before{content:'';position:absolute;inset:3px;border:1px solid rgba(255,255,255,0.3)}
.logo-icon{display:flex;gap:4px}
.logo-dot{width:14px;height:14px;background:white;border-radius:50%}
.logo-text{font-family:'Playfair Display',serif;color:white;font-size:18px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.hr-badge{background:var(--hr);color:white;padding:8px 20px;font-size:11px;font-weight:600;
letter-spacing:.1em;text-transform:uppercase;margin-bottom:20px;display:flex;align-items:center;gap:8px}
.card{background:var(--white);width:100%;max-width:660px;border-radius:2px;box-shadow:var(--shadow-lg);overflow:hidden}
.card-header{background:var(--hr);padding:28px 36px;display:flex;align-items:flex-start;justify-content:space-between;position:relative}
.card-header::before{content:'';position:absolute;right:40px;top:0;bottom:0;width:4px;background:var(--orange)}
.card-header h1{font-family:'Playfair Display',serif;color:white;font-size:22px;font-weight:600}
.card-header p{color:rgba(255,255,255,0.5);font-size:12px;margin-top:4px}
.hdr-badge{background:rgba(232,93,4,0.2);color:var(--orange-mid);border:1px solid rgba(232,93,4,0.3);
padding:6px 14px;font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase}
.card-body{padding:32px 36px}
.trail{display:flex;background:var(--grey-light);border:1px solid var(--border);overflow:hidden;margin-bottom:24px}
.trail-step{flex:1;padding:12px 16px;text-align:center;position:relative;font-size:12px}
.trail-step::after{content:'›';position:absolute;right:-6px;top:50%;transform:translateY(-50%);color:var(--border);font-size:20px;z-index:1}
.trail-step:last-child::after{display:none}
.trail-step .ts-icon{font-size:18px;margin-bottom:4px}
.trail-step .ts-label{font-size:10px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--grey-mid);margin-bottom:2px}
.trail-step .ts-status{font-size:11px;font-weight:600;color:var(--grey-mid)}
.trail-step.done{background:var(--success-light)}
.trail-step.done .ts-status{color:var(--success)}
.trail-step.current{background:var(--hr-light);border-bottom:3px solid var(--hr)}
.trail-step.current .ts-label{color:var(--hr)}
.trail-step.current .ts-status{color:var(--hr)}
.section-label{font-size:10px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;
color:var(--hr);margin-bottom:14px;padding-bottom:8px;border-bottom:1px solid var(--hr-mid);margin-top:24px}
.section-label:first-of-type{margin-top:0}
.emp-profile{display:flex;align-items:center;gap:16px;padding:16px 20px;
background:var(--hr-light);border:1px solid var(--hr-mid);margin-bottom:16px}
.emp-avatar{width:52px;height:52px;background:var(--hr);border-radius:50%;display:flex;
align-items:center;justify-content:center;font-family:'Playfair Display',serif;font-size:20px;font-weight:700;color:white;flex-shrink:0}
.emp-info h3{font-size:16px;font-weight:600;color:var(--black)}
.emp-info p{font-size:12px;color:var(--hr);margin-top:2px}
.emp-tags{display:flex;gap:8px;margin-top:6px;flex-wrap:wrap}
.emp-tag{background:white;border:1px solid var(--hr-mid);padding:3px 8px;font-size:11px;color:var(--hr);font-weight:500}
.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px}
.detail-item{background:var(--grey-light);border:1px solid var(--border);padding:12px 14px}
.detail-item.full{grid-column:1/-1}
.di-label{font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--grey-mid);margin-bottom:4px}
.di-value{font-size:14px;font-weight:500;color:var(--black)}
.leave-chip{display:inline-block;background:var(--hr);color:white;padding:4px 12px;font-size:13px;font-weight:600}
.days-block{background:var(--black);color:white;padding:20px 24px;display:flex;
align-items:center;justify-content:space-between;margin-bottom:16px}
.db-label{font-size:11px;color:rgba(255,255,255,0.5);text-transform:uppercase;letter-spacing:.08em;margin-bottom:4px}
.db-period{font-size:14px;font-weight:500;color:white}
.big-days{font-family:'Playfair Display',serif;font-size:36px;font-weight:700;color:var(--orange);line-height:1}
.db-sub{font-size:11px;color:rgba(255,255,255,0.4);text-align:right;margin-top:2px}
.balance-card{border:1px solid var(--border);padding:16px 20px;margin-bottom:16px}
.bc-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}
.bc-label{font-size:12px;font-weight:600;color:var(--grey-dark);text-transform:uppercase;letter-spacing:.04em}
.bc-val{font-size:15px;font-weight:700;color:var(--black)}
.balance-bar{height:8px;background:var(--border);border-radius:4px;overflow:hidden;margin-bottom:6px}
.balance-fill{height:100%;border-radius:4px;background:var(--success);transition:width .8s ease}
.balance-fill.mid{background:#D4AC00}
.balance-fill.low{background:var(--error)}
.bc-meta{display:flex;justify-content:space-between;font-size:11px;color:var(--grey-mid)}
.mgr-decision{border:1px solid var(--success);background:var(--success-light);padding:16px 20px;margin-bottom:20px}
.mgr-decision .md-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}
.mgr-decision .md-label{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--success)}
.mgr-decision .md-badge{background:var(--success);color:white;padding:3px 10px;font-size:11px;font-weight:600;letter-spacing:.06em}
.mgr-decision .md-name{font-size:14px;font-weight:500;color:var(--black);margin-bottom:4px}
.mgr-decision .md-comment{font-size:13px;color:var(--grey-dark);font-style:italic}
.hr-checklist{border:1px solid var(--hr-mid);background:var(--hr-light);padding:16px 20px;margin-bottom:20px}
.hc-title{font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--hr);margin-bottom:14px}
.check-item{display:flex;align-items:flex-start;gap:10px;padding:8px 0;border-bottom:1px solid var(--hr-mid);cursor:pointer}
.check-item:last-child{border-bottom:none}
.check-item input[type=checkbox]{width:16px;height:16px;accent-color:var(--hr);margin-top:2px;flex-shrink:0;cursor:pointer}
.check-item .ci-text{font-size:13px;color:var(--grey-dark);line-height:1.4}
.check-item .ci-text.checked{text-decoration:line-through;color:var(--grey-mid)}
.already-decided{padding:20px;text-align:center;font-size:14px;font-weight:500;margin-bottom:20px;display:none}
.already-decided.approved{background:var(--success-light);color:var(--success);border:1px solid rgba(45,106,79,0.3)}
.already-decided.rejected{background:var(--error-light);color:var(--error);border:1px solid rgba(193,18,31,0.3)}
.decision-opts{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:20px}
.d-btn{border:2px solid var(--border);background:var(--white);padding:20px 16px;cursor:pointer;
font-family:'DM Sans',sans-serif;transition:all .2s ease;text-align:center}
.d-btn .d-icon{font-size:28px;margin-bottom:8px}
.d-btn .d-label{font-size:14px;font-weight:600;color:var(--grey-dark);display:block;margin-bottom:4px}
.d-btn .d-sub{font-size:11px;color:var(--grey-mid)}
.d-btn:hover{transform:translateY(-2px)}
.d-btn.approve:hover,.d-btn.approve.selected{border-color:var(--success);background:var(--success-light)}
.d-btn.approve.selected .d-label{color:var(--success)}
.d-btn.reject:hover,.d-btn.reject.selected{border-color:var(--error);background:var(--error-light)}
.d-btn.reject.selected .d-label{color:var(--error)}
.override-warn{background:#FFF8E0;border:1px solid #D4AC00;border-left:3px solid #D4AC00;
padding:12px 14px;font-size:12px;color:#6B5A00;line-height:1.5;margin-bottom:16px;display:none}
.override-warn.show{display:block}
.comment-area{display:flex;flex-direction:column;gap:6px;margin-bottom:20px}
.comment-area label{font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--grey-dark)}
.comment-area textarea{padding:14px;border:2px solid var(--border);font-family:'DM Sans',sans-serif;
font-size:14px;color:var(--black);resize:vertical;min-height:90px;outline:none;transition:border-color .2s}
.comment-area textarea:focus{border-color:var(--hr)}
.btn{width:100%;padding:16px;border:none;font-family:'DM Sans',sans-serif;font-size:14px;font-weight:600;
letter-spacing:.06em;text-transform:uppercase;cursor:pointer;transition:all .2s ease}
.btn-approve{background:var(--success);color:white}
.btn-approve:hover{background:#1f5e40;transform:translateY(-1px)}
.btn-reject{background:var(--error);color:white}
.btn-reject:hover{background:#9B0E1A;transform:translateY(-1px)}
.btn:disabled{background:var(--grey-mid);cursor:not-allowed;transform:none}
.alert{padding:12px 16px;font-size:13px;font-weight:500;margin-bottom:16px;display:none;align-items:center;gap:10px}
.alert.show{display:flex}
.alert.error{background:var(--error-light);color:var(--error);border-left:3px solid var(--error)}
.success-state{padding:48px 36px;text-align:center;display:none}
.success-state.active{display:block}
.s-icon{font-size:52px;margin-bottom:16px}
.success-state h3{font-family:'Playfair Display',serif;font-size:20px;color:var(--black);margin-bottom:8px}
.success-state p{color:var(--grey-mid);font-size:14px;line-height:1.6;max-width:400px;margin:0 auto}
.footer-note{font-size:11px;color:var(--grey-mid);text-align:center;margin-top:28px;letter-spacing:.03em}
.spinner{width:16px;height:16px;border:2px solid rgba(255,255,255,0.4);border-top-color:white;
border-radius:50%;animation:spin .8s linear infinite;display:inline-block;vertical-align:middle;margin-right:6px}
@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:520px){.card-body{padding:24px 20px}.detail-grid,.decision-opts{grid-template-columns:1fr}
.card-header{padding:20px 24px;flex-direction:column;gap:12px}.trail{flex-direction:column}
.trail-step::after{display:none}}
</style>
</head>
<body>
<div class="logo-wrap">
  <div class="logo-badge">
    <div class="logo-icon"><div class="logo-dot"></div><div class="logo-dot"></div></div>
    <div class="logo-text">Orange Group</div>
  </div>
</div>
<div class="hr-badge">🏛️ &nbsp; Human Resources · Final Approval Portal</div>
<div class="card">
  <div class="card-header">
    <div><h1>HR Final Review</h1><p>Manager has approved · Your decision is final</p></div>
    <div class="hdr-badge">Step 3 of 3</div>
  </div>
  <div class="card-body" id="cardBody">
    <div class="trail">
      <div class="trail-step done"><div class="ts-icon">📝</div><div class="ts-label">Employee</div><div class="ts-status">Submitted</div></div>
      <div class="trail-step done"><div class="ts-icon">👤</div><div class="ts-label">Manager</div><div class="ts-status">Approved</div></div>
      <div class="trail-step current"><div class="ts-icon">🏛️</div><div class="ts-label">HR</div><div class="ts-status">Pending</div></div>
      <div class="trail-step"><div class="ts-icon">✅</div><div class="ts-label">Final</div><div class="ts-status">Awaiting</div></div>
    </div>
    <div class="section-label">Employee</div>
    <div class="emp-profile">
      <div class="emp-avatar" id="d_avatar">—</div>
      <div class="emp-info">
        <h3 id="d_name">—</h3><p id="d_email">—</p>
        <div class="emp-tags">
          <span class="emp-tag" id="d_role">—</span>
          <span class="emp-tag" id="d_dept">—</span>
          <span class="emp-tag" id="d_empid">—</span>
        </div>
      </div>
    </div>
    <div class="section-label">Leave Request Details</div>
    <div class="detail-grid">
      <div class="detail-item full"><div class="di-label">Type of Leave</div><div class="di-value"><span class="leave-chip" id="d_type">—</span></div></div>
      <div class="detail-item"><div class="di-label">Start Date</div><div class="di-value" id="d_start">—</div></div>
      <div class="detail-item"><div class="di-label">End Date</div><div class="di-value" id="d_end">—</div></div>
      <div class="detail-item"><div class="di-label">Resumption Date</div><div class="di-value" id="d_res">—</div></div>
      <div class="detail-item"><div class="di-label">Reliever</div><div class="di-value" id="d_rel">—</div></div>
      <div class="detail-item full"><div class="di-label">Contact During Leave</div><div class="di-value" id="d_addr">—</div></div>
      <div class="detail-item"><div class="di-label">Phone</div><div class="di-value" id="d_phone">—</div></div>
      <div class="detail-item"><div class="di-label">Days Previously Taken</div><div class="di-value" id="d_prev">—</div></div>
    </div>
    <div class="days-block">
      <div><div class="db-label">Leave Period</div><div class="db-period" id="d_period">—</div></div>
      <div style="text-align:right"><div class="big-days" id="d_days">—</div><div class="db-sub">working days</div></div>
    </div>
    <div class="balance-card" id="balCard">
      <div class="bc-header"><span class="bc-label">Annual Leave Balance</span><span class="bc-val" id="bc_val">—</span></div>
      <div class="balance-bar"><div class="balance-fill" id="bc_fill" style="width:0%"></div></div>
      <div class="bc-meta"><span id="bc_used">—</span><span id="bc_total">—</span></div>
    </div>
    <div class="section-label">Manager Decision</div>
    <div class="mgr-decision">
      <div class="md-head"><div class="md-label">Manager Review</div><div class="md-badge">✅ Approved</div></div>
      <div class="md-name" id="d_mgrName">—</div>
      <div class="md-comment" id="d_mgrComment">No comments provided.</div>
    </div>
    <div class="section-label">HR Verification Checklist</div>
    <div class="hr-checklist">
      <div class="hc-title">Confirm before approving</div>
      <label class="check-item"><input type="checkbox" onchange="toggleCheck(this)"><span class="ci-text">Leave period does not conflict with critical business operations</span></label>
      <label class="check-item"><input type="checkbox" onchange="toggleCheck(this)"><span class="ci-text">Employee leave balance is sufficient (Annual Leave only)</span></label>
      <label class="check-item"><input type="checkbox" onchange="toggleCheck(this)"><span class="ci-text">Reliever is confirmed and available during this period</span></label>
      <label class="check-item"><input type="checkbox" onchange="toggleCheck(this)"><span class="ci-text">Minimum notice period has been observed per policy</span></label>
      <label class="check-item"><input type="checkbox" onchange="toggleCheck(this)"><span class="ci-text">Leave record will be updated in HR records upon approval</span></label>
    </div>
    <div class="already-decided" id="alreadyDecided"></div>
    <div id="decisionSection">
      <div class="section-label">HR Decision</div>
      <div class="override-warn" id="overrideWarn">⚠️ <strong>Overriding Manager:</strong> You are rejecting a request the manager approved. Both the employee and manager will be notified with your comments.</div>
      <div class="decision-opts">
        <button class="d-btn approve" onclick="selectDecision('approve',this)">
          <div class="d-icon">✅</div><span class="d-label">Final Approve</span><span class="d-sub">Balance deducted, employee notified</span>
        </button>
        <button class="d-btn reject" onclick="selectDecision('reject',this)">
          <div class="d-icon">❌</div><span class="d-label">Reject</span><span class="d-sub">Override manager, notify all parties</span>
        </button>
      </div>
      <div class="comment-area">
        <label>HR Comments <span style="color:var(--grey-mid);font-weight:400;text-transform:none;letter-spacing:0">(required if rejecting)</span></label>
        <textarea id="f_comment" placeholder="Add HR notes, conditions, or reason for rejection…"></textarea>
      </div>
      <div class="alert error" id="submitError"><span>⚠</span><span id="submitErrorMsg">Something went wrong.</span></div>
      <button class="btn btn-approve" id="submitBtn" onclick="submitDecision()" disabled>Submit HR Decision</button>
    </div>
  </div>
  <div class="success-state" id="successState">
    <div class="s-icon" id="s_icon">✅</div>
    <h3 id="s_heading">Decision Recorded</h3>
    <p id="s_msg">The employee has been notified and HR records will be updated accordingly.</p>
  </div>
</div>
<div class="footer-note">Orange Group Leave Management System · HR Portal · Strictly Confidential</div>
<script>
const D = JSON.parse(atob('${encoded}'));
const N8N_BASE = '[URL]';
let selectedDecision = null;

function fmtDate(s){try{return new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});}catch{return s||'—';}}
function toggleCheck(cb){cb.closest('.check-item').querySelector('.ci-text').classList.toggle('checked',cb.checked);}

function init(){
  const initials=(D.EmployeeName||'??').split(' ').map(n=>n[0]).join('').slice(0,2).toUpperCase();
  document.getElementById('d_avatar').textContent=initials;
  document.getElementById('d_name').textContent=D.EmployeeName||'—';
  document.getElementById('d_email').textContent=D.EmployeeEmail||'—';
  document.getElementById('d_role').textContent=D.Role||'—';
  document.getElementById('d_dept').textContent=D.Department||'—';
  document.getElementById('d_empid').textContent=D.EmployeeID||'—';
  document.getElementById('d_type').textContent=D.LeaveType||'—';
  document.getElementById('d_start').textContent=fmtDate(D.StartDate);
  document.getElementById('d_end').textContent=fmtDate(D.EndDate);
  document.getElementById('d_res').textContent=fmtDate(D.ResumptionDate);
  document.getElementById('d_rel').textContent=D.Reliever||'—';
  document.getElementById('d_addr').textContent=D.ContactAddress||'—';
  document.getElementById('d_phone').textContent=D.PhoneNumber||'—';
  document.getElementById('d_prev').textContent=D.DaysPreviousTaken||'0';
  document.getElementById('d_period').textContent=fmtDate(D.StartDate)+' → '+fmtDate(D.EndDate);
  document.getElementById('d_days').textContent=D.NumberOfDays||'—';

  if(D.LeaveType==='Annual Leave'){
    const total=parseFloat(D.TotalLeaveDays)||20;
    const balance=parseFloat(D.LeaveBalance)||0;
    const used=total-balance;
    const requested=parseInt(D.NumberOfDays)||0;
    const pct=Math.min(100,((used+requested)/total)*100);
    document.getElementById('bc_val').textContent=balance+' days remaining';
    document.getElementById('bc_used').textContent=used+' used + '+requested+' requested';
    document.getElementById('bc_total').textContent='of '+total+' total';
    const fill=document.getElementById('bc_fill');
    setTimeout(()=>fill.style.width=pct+'%',100);
    if(pct>90)fill.classList.add('low');
    else if(pct>70)fill.classList.add('mid');
  } else {
    document.getElementById('balCard').style.display='none';
  }

  document.getElementById('d_mgrName').textContent='Approved by: '+(D.ManagerName||'—')+' · '+fmtDate(D.ManagerDecisionDate);
  document.getElementById('d_mgrComment').textContent=D.ManagerComment||'No comments provided.';

  if(D.HRStatus && D.HRStatus!=='Pending'){
    const ad=document.getElementById('alreadyDecided');
    ad.style.display='block';
    ad.textContent='This request was already '+D.HRStatus.toLowerCase()+' by HR on '+fmtDate(D.HRDecisionDate)+'.';
    ad.className='already-decided '+(D.HRStatus==='Approved'?'approved':'rejected');
    document.getElementById('decisionSection').style.display='none';
  }
}

function selectDecision(dec,btn){
  selectedDecision=dec;
  document.querySelectorAll('.d-btn').forEach(b=>b.classList.remove('selected'));
  btn.classList.add('selected');
  const sb=document.getElementById('submitBtn');
  sb.disabled=false;
  const ow=document.getElementById('overrideWarn');
  if(dec==='approve'){sb.className='btn btn-approve';sb.textContent='✅ Final Approve — Notify Employee';ow.classList.remove('show');}
  else{sb.className='btn btn-reject';sb.textContent='❌ Reject — Override Manager Decision';ow.classList.add('show');}
}

async function submitDecision(){
  if(!selectedDecision) return;
  if(selectedDecision==='reject'&&!document.getElementById('f_comment').value.trim()){
    document.getElementById('f_comment').style.borderColor='var(--error)';
    document.getElementById('f_comment').focus(); return;
  }
  const btn=document.getElementById('submitBtn');
  btn.disabled=true;
  btn.innerHTML='<span class="spinner"></span>Submitting…';
  document.getElementById('submitError').classList.remove('show');
  try{
    const res=await fetch(N8N_BASE+'/submit-hr-decision',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({requestId:D.RequestID,decision:selectedDecision,
        comment:document.getElementById('f_comment').value.trim(),
        employeeId:D.EmployeeID,numberOfDays:D.NumberOfDays,leaveType:D.LeaveType})
    });
    if(!res.ok) throw new Error('Server error');
    const isApprove=selectedDecision==='approve';
    document.getElementById('s_icon').textContent=isApprove?'✅':'❌';
    document.getElementById('s_heading').textContent=isApprove?'Leave Approved':'Leave Rejected';
    document.getElementById('s_msg').textContent=isApprove
      ?D.EmployeeName+' has been notified. Leave balance has been updated.'
      :'Request rejected. '+D.EmployeeName+' and their manager have been notified with your reason.';
    document.getElementById('cardBody').style.display='none';
    document.getElementById('successState').classList.add('active');
  }catch(err){
    document.getElementById('submitError').classList.add('show');
    document.getElementById('submitErrorMsg').textContent='Submission failed. Please try again or contact IT.';
    btn.disabled=false;
    btn.textContent=selectedDecision==='approve'?'✅ Final Approve — Notify Employee':'❌ Reject — Override Manager Decision';
  }
}

init();
</script>
</body>
</html>`;

return [{ json: { html } }];

// BUILD: Employee Leave Request Form
// Encodes employee data as base64 and injects into table_3-contained HTML

const employees = $input.all().map(i => i.json);
const encoded = Buffer.from(JSON.stringify(employees)).toString('base64');

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leave Application — Orange Group</title>
<link href="[URL]" rel="stylesheet">
<style>
  :root {
    --orange:#E85D04;--orange-dark:#C44B00;--orange-light:#FFF3ED;--orange-mid:#FFD6B8;
    --black:#1A1008;--grey-dark:#3D3028;--grey-mid:#8A7A6E;--grey-light:#F5F0EB;
    --white:#FFFFFF;--border:#E8DDD5;--success:#2D6A4F;--error:#C1121F;
    --shadow-lg:0 12px 48px rgba(232,93,4,0.16);
  }
  *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
  body{font-family:'DM Sans',sans-serif;background:var(--grey-light);min-height:100vh;
    display:flex;flex-direction:column;align-items:center;padding:40px 16px 80px;overflow-x:hidden}
  body::before{content:'';position:fixed;top:-200px;right:-200px;width:600px;height:600px;
    background:radial-gradient(circle,rgba(232,93,4,0.08) 0%,transparent 70%);pointer-events:none}

  .logo-wrap{margin-bottom:32px;animation:fadeDown .6s ease both}
  .logo-badge{background:var(--orange);border:2px solid var(--orange-dark);display:inline-flex;
    align-items:center;gap:10px;padding:10px 28px;position:relative}
  .logo-badge::before{content:'';position:absolute;inset:3px;border:1px solid rgba(255,255,255,0.3);pointer-events:none}
  .logo-icon{display:flex;gap:4px}
  .logo-dot{width:14px;height:14px;background:white;border-radius:50%;position:relative;overflow:hidden}
  .logo-dot::after{content:'';position:absolute;bottom:0;left:0;right:0;height:40%;background:rgba(0,0,0,0.15)}
  .logo-text{font-family:'Playfair Display',serif;color:white;font-size:18px;font-weight:700;
    letter-spacing:0.12em;text-transform:uppercase}

  .card{background:var(--white);width:100%;max-width:600px;border-radius:2px;
    box-shadow:var(--shadow-lg);overflow:hidden;animation:fadeUp .7s ease both;animation-delay:.1s}
  .card-header{background:var(--orange);padding:28px 36px;position:relative;overflow:hidden}
  .card-header::after{content:'';position:absolute;right:-30px;bottom:-30px;width:120px;height:120px;
    border:2px solid rgba(255,255,255,0.15);border-radius:50%}
  .card-header h1{font-family:'Playfair Display',serif;color:white;font-size:22px;font-weight:600}
  .card-header p{color:rgba(255,255,255,0.8);font-size:13px;margin-top:4px;font-weight:300;letter-spacing:.02em}

  .progress-bar{display:flex;border-bottom:1px solid var(--border)}
  .progress-step{flex:1;padding:14px 16px;display:flex;align-items:center;gap:10px;font-size:12px;
    font-weight:500;color:var(--grey-mid);letter-spacing:.06em;text-transform:uppercase;
    transition:all .3s ease;border-bottom:3px solid transparent}
  .progress-step.active{color:var(--orange);border-bottom-color:var(--orange)}
  .progress-step.done{color:var(--success);border-bottom-color:var(--success)}
  .step-num{width:22px;height:22px;border-radius:50%;border:2px solid currentColor;display:flex;
    align-items:center;justify-content:center;font-size:11px;font-weight:600;flex-shrink:0;transition:all .3s ease}
  .progress-step.done .step-num{background:var(--success);color:white;border-color:var(--success)}

  .form-body{padding:36px}
  .page{display:none}
  .page.active{display:block;animation:fadeIn .4s ease}

  .id-lookup{text-align:center;padding:16px 0 8px}
  .id-icon{width:64px;height:64px;background:var(--orange-light);border-radius:50%;
    display:flex;align-items:center;justify-content:center;margin:0 auto 20px;font-size:28px}
  .id-lookup h2{font-family:'Playfair Display',serif;font-size:20px;color:var(--black);margin-bottom:8px}
  .id-lookup p{color:var(--grey-mid);font-size:14px;line-height:1.6;margin-bottom:32px}

  .id-input-group{position:relative;max-width:320px;margin:0 auto 12px}
  .id-prefix{position:absolute;left:16px;top:50%;transform:translateY(-50%);font-size:13px;
    font-weight:600;color:var(--orange);letter-spacing:.05em;pointer-events:none}
  .id-input-group input{width:100%;padding:16px 16px 16px 64px;font-size:20px;
    font-family:'DM Sans',sans-serif;font-weight:600;letter-spacing:.12em;border:2px solid var(--border);
    border-radius:2px;background:var(--grey-light);color:var(--black);text-align:center;
    transition:all .2s ease;outline:none}
  .id-input-group input:focus{border-color:var(--orange);background:var(--white);
    box-shadow:0 0 0 4px rgba(232,93,4,0.08)}
  .id-hint{font-size:12px;color:var(--grey-mid);margin-bottom:28px}

  .alert{padding:12px 16px;border-radius:2px;font-size:13px;font-weight:500;margin-bottom:20px;
    display:none;align-items:center;gap:10px;animation:fadeIn .3s ease}
  .alert.show{display:flex}
  .alert.error{background:#FFF0F0;color:var(--error);border-left:3px solid var(--error)}
  .alert.info{background:var(--orange-light);color:var(--orange-dark);border-left:3px solid var(--orange)}

  .section-label{font-size:10px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;
    color:var(--orange);margin-bottom:16px;padding-bottom:8px;border-bottom:1px solid var(--orange-mid)}
  .prefilled-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:28px}
  .prefilled-field{background:var(--grey-light);border:1px solid var(--border);border-radius:2px;
    padding:12px 14px;position:relative}
  .prefilled-field.full{grid-column:1/-1}
  .prefilled-field label{font-size:10px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;
    color:var(--grey-mid);display:block;margin-bottom:4px}
  .prefilled-field .value{font-size:14px;font-weight:500;color:var(--black)}
  .prefilled-field .lock{position:absolute;top:12px;right:12px;font-size:11px;color:var(--grey-mid);opacity:.5}

  .balance-pill{background:var(--orange-light);border:1px solid var(--orange-mid);border-radius:2px;
    padding:14px 16px;display:flex;align-items:center;justify-content:space-between;margin-bottom:28px}
  .balance-pill .bp-label{font-size:12px;font-weight:500;color:var(--orange-dark);letter-spacing:.04em}
  .balance-pill .bp-sub{font-size:11px;color:var(--grey-mid);margin-top:2px}
  .balance-pill .bp-days{font-family:'Playfair Display',serif;font-size:24px;font-weight:700;color:var(--orange)}
  .balance-pill .bp-days span{font-family:'DM Sans',sans-serif;font-size:13px;font-weight:400;
    color:var(--orange-dark);margin-left:4px}

  .leave-types{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:28px}
  .lt-btn{border:2px solid var(--border);background:var(--white);border-radius:2px;padding:12px 14px;
    cursor:pointer;font-family:'DM Sans',sans-serif;font-size:13px;font-weight:500;color:var(--grey-dark);
    text-align:left;transition:all .2s ease;display:flex;align-items:center;gap:8px}
  .lt-btn:hover{border-color:var(--orange);background:var(--orange-light);color:var(--orange-dark)}
  .lt-btn.selected{border-color:var(--orange);background:var(--orange);color:white}
  .lt-dot{width:8px;height:8px;border-radius:50%;border:2px solid currentColor;flex-shrink:0;transition:all .2s}
  .lt-btn.selected .lt-dot{background:white;border-color:white}

  .notice-box{background:var(--orange-light);border:1px solid var(--orange-mid);
    border-left:3px solid var(--orange);padding:12px 14px;border-radius:2px;font-size:12px;
    color:var(--orange-dark);margin-bottom:20px;line-height:1.5;display:none}
  .notice-box.show{display:block}

  .fields-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px}
  .field-group{display:flex;flex-direction:column;gap:6px}
  .field-group.full{grid-column:1/-1}
  .field-group label{font-size:11px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;color:var(--grey-dark)}
  .field-group label .req{color:var(--orange);margin-left:2px}
  .field-group input,.field-group select,.field-group textarea{padding:12px 14px;border:2px solid var(--border);
    border-radius:2px;font-family:'DM Sans',sans-serif;font-size:14px;color:var(--black);
    background:var(--white);outline:none;transition:all .2s ease;width:100%}
  .field-group input:focus,.field-group select:focus,.field-group textarea:focus{
    border-color:var(--orange);box-shadow:0 0 0 4px rgba(232,93,4,0.08)}
  .field-group input[readonly]{background:var(--grey-light);color:var(--grey-mid);cursor:not-allowed}
  .field-group textarea{resize:vertical;min-height:80px}
  .field-group.has-error input,.field-group.has-error select,.field-group.has-error textarea{border-color:var(--error)}
  .field-error{font-size:11px;color:var(--error);margin-top:2px;display:none}
  .field-group.has-error .field-error{display:block}

  .days-summary{background:var(--black);color:white;border-radius:2px;padding:16px 20px;
    display:flex;align-items:center;justify-content:space-between;margin-bottom:28px;display:none}
  .days-summary.show{display:flex}
  .ds-label{font-size:12px;font-weight:500;color:rgba(255,255,255,0.6);letter-spacing:.06em;text-transform:uppercase}
  .ds-value{font-family:'Playfair Display',serif;font-size:28px;font-weight:700;color:var(--orange)}
  .ds-value span{font-family:'DM Sans',sans-serif;font-size:13px;color:rgba(255,255,255,0.5)}

  .policy-note{background:var(--grey-light);border-radius:2px;padding:14px 16px;font-size:12px;
    color:var(--grey-mid);line-height:1.6;margin-bottom:28px;border-left:3px solid var(--border)}

  .btn{width:100%;padding:16px;border:none;border-radius:2px;font-family:'DM Sans',sans-serif;
    font-size:14px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;cursor:pointer;
    transition:all .2s ease}
  .btn-primary{background:var(--orange);color:white}
  .btn-primary:hover{background:var(--orange-dark);transform:translateY(-1px);
    box-shadow:0 6px 20px rgba(232,93,4,0.3)}
  .btn-primary:disabled{background:var(--grey-mid);cursor:not-allowed;transform:none;box-shadow:none}
  .btn-back{background:transparent;color:var(--grey-mid);border:2px solid var(--border);margin-bottom:12px}
  .btn-back:hover{border-color:var(--grey-dark);color:var(--grey-dark)}

  .success-page{text-align:center;padding:20px 0}
  .success-icon{width:72px;height:72px;background:#EDFAF3;border-radius:50%;display:flex;
    align-items:center;justify-content:center;margin:0 auto 20px;font-size:32px}
  .success-page h2{font-family:'Playfair Display',serif;font-size:22px;color:var(--black);margin-bottom:8px}
  .success-page p{color:var(--grey-mid);font-size:14px;line-height:1.6;max-width:360px;margin:0 auto 28px}
  .success-detail{background:var(--grey-light);border-radius:2px;padding:20px;text-align:left;margin-bottom:24px}
  .sdr{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border);font-size:13px}
  .sdr:last-child{border-bottom:none}
  .sdr .sd-l{color:var(--grey-mid)}
  .sdr .sd-v{font-weight:600;color:var(--black)}

  .footer-note{font-size:11px;color:var(--grey-mid);text-align:center;margin-top:28px;letter-spacing:.03em}
  .spinner{width:16px;height:16px;border:2px solid rgba(255,255,255,0.4);border-top-color:white;
    border-radius:50%;animation:spin .8s linear infinite;display:inline-block;vertical-align:middle;margin-right:6px}

  @keyframes fadeDown{from{opacity:0;transform:translateY(-20px)}to{opacity:1;transform:translateY(0)}}
  @keyframes fadeUp{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}
  @keyframes fadeIn{from{opacity:0}to{opacity:1}}
  @keyframes spin{to{transform:rotate(360deg)}}

  @media(max-width:520px){
    .form-body{padding:24px 20px}
    .prefilled-grid,.fields-grid,.leave-types{grid-template-columns:1fr}
    .prefilled-field.full{grid-column:1}
    .card-header{padding:20px 24px}
  }
</style>
</head>
<body>

<div class="logo-wrap">
  <div class="logo-badge">
    <div class="logo-icon"><div class="logo-dot"></div><div class="logo-dot"></div></div>
    <div class="logo-text">Orange Group</div>
  </div>
</div>

<div class="card">
  <div class="card-header">
    <h1>Leave Application</h1>
    <p>Submit your leave request for manager &amp; HR review</p>
  </div>

  <div class="progress-bar">
    <div class="progress-step active" id="si1"><div class="step-num">1</div>Verify Identity</div>
    <div class="progress-step" id="si2"><div class="step-num">2</div>Request Details</div>
    <div class="progress-step" id="si3"><div class="step-num">3</div>Confirmation</div>
  </div>

  <div class="form-body">

    <!-- PAGE 1 -->
    <div class="page active" id="page1">
      <div class="id-lookup">
        <div class="id-icon">🪪</div>
        <h2>Enter Your Employee ID</h2>
        <p>Your details will be automatically pulled from table_4 records. No manual entry required.</p>
        <div class="id-input-group">
          <div class="id-prefix">ODL</div>
          <input type="text" id="empId" placeholder="0000" maxlength="6" inputmode="numeric" autocomplete="off">
        </div>
        <div class="id-hint">Your Staff ID number (e.g. ODL0700)</div>
        <div class="alert error" id="lookupError"><span>⚠</span><span id="lookupErrorMsg">Employee ID not found.</span></div>
      </div>
      <button class="btn btn-primary" id="lookupBtn" onclick="lookupEmployee()" disabled>Continue →</button>
    </div>

    <!-- PAGE 2 -->
    <div class="page" id="page2">
      <input type="hidden" id="f_employeeId">
      <input type="hidden" id="f_leaveType" value="">

      <div class="section-label">Your Details</div>
      <div class="prefilled-grid">
        <div class="prefilled-field"><label>Full Name</label><div class="value" id="d_name">—</div><div class="lock">🔒</div></div>
        <div class="prefilled-field"><label>Staff ID</label><div class="value" id="d_id">—</div><div class="lock">🔒</div></div>
        <div class="prefilled-field"><label>Department</label><div class="value" id="d_dept">—</div><div class="lock">🔒</div></div>
        <div class="prefilled-field"><label>Branch</label><div class="value" id="d_branch">—</div><div class="lock">🔒</div></div>
        <div class="prefilled-field full"><label>Job Role</label><div class="value" id="d_role">—</div><div class="lock">🔒</div></div>
        <div class="prefilled-field full"><label>Line Manager</label><div class="value" id="d_manager">—</div><div class="lock">🔒</div></div>
      </div>

      <div class="balance-pill" id="balancePill">
        <div><div class="bp-label">Annual Leave Balance</div><div class="bp-sub" id="d_usedLabel"></div></div>
        <div class="bp-days" id="d_balance">— <span>days remaining</span></div>
      </div>

      <div class="section-label">Type of Leave</div>
      <div class="leave-types">
        <button type="button" class="lt-btn" onclick="selectLeave(this,'Annual Leave')"><div class="lt-dot"></div>Annual Leave</button>
        <button type="button" class="lt-btn" onclick="selectLeave(this,'Sick Leave')"><div class="lt-dot"></div>Sick Leave</button>
        <button type="button" class="lt-btn" onclick="selectLeave(this,'Casual Leave')"><div class="lt-dot"></div>Casual Leave</button>
        <button type="button" class="lt-btn" onclick="selectLeave(this,'Compassionate Leave')"><div class="lt-dot"></div>Compassionate Leave</button>
        <button type="button" class="lt-btn" onclick="selectLeave(this,'Maternity Leave')"><div class="lt-dot"></div>Maternity Leave</button>
        <button type="button" class="lt-btn" onclick="selectLeave(this,'Paternity Leave')"><div class="lt-dot"></div>Paternity Leave</button>
        <button type="button" class="lt-btn" onclick="selectLeave(this,'Leave of Absence')"><div class="lt-dot"></div>Leave of Absence</button>
        <button type="button" class="lt-btn" onclick="selectLeave(this,'Examination Leave')"><div class="lt-dot"></div>Examination Leave</button>
      </div>
      <div class="notice-box" id="leaveNotice"></div>

      <div class="section-label">Leave Period</div>
      <div class="fields-grid">
        <div class="field-group"><label>Start Date <span class="req">*</span></label>
          <input type="date" id="f_start" onchange="calcDays()">
          <div class="field-error">Required</div></div>
        <div class="field-group"><label>End Date <span class="req">*</span></label>
          <input type="date" id="f_end" onchange="calcDays()">
          <div class="field-error">Must be after start date</div></div>
        <div class="field-group"><label>Resumption Date</label>
          <input type="date" id="f_resumption" readonly></div>
        <div class="field-group"><label>Days Previously Taken</label>
          <input type="text" id="d_prevDays" readonly></div>
      </div>

      <div class="days-summary" id="daysSummary">
        <div class="ds-label">Days Requested</div>
        <div class="ds-value" id="ds_days">0 <span>working days</span></div>
      </div>
      <div class="alert error" id="balanceError"><span>⚠</span><span id="balanceErrorMsg"></span></div>

      <div class="section-label">Additional Details</div>
      <div class="fields-grid">
        <div class="field-group full"><label>Name of Reliever <span class="req">*</span></label>
          <select id="f_reliever"><option value="">— Select reliever —</option></select>
          <div class="field-error">Please select a reliever</div></div>
        <div class="field-group full"><label>Contact Address During Leave <span class="req">*</span></label>
          <textarea id="f_address" placeholder="Full address where you can be reached…"></textarea>
          <div class="field-error">Please provide your contact address</div></div>
        <div class="field-group"><label>Phone Number <span class="req">*</span></label>
          <input type="tel" id="f_phone" placeholder="080XXXXXXXX">
          <div class="field-error">Please enter your phone number</div></div>
      </div>

      <div class="policy-note" id="policyNote"></div>
      <div class="alert error" id="submitError"><span>⚠</span><span id="submitErrorMsg">Something went wrong.</span></div>

      <button class="btn btn-back" onclick="goBack()">← Change Employee ID</button>
      <button class="btn btn-primary" id="submitBtn" onclick="submitRequest()">Submit Leave Request</button>
    </div>

    <!-- PAGE 3 -->
    <div class="page" id="page3">
      <div class="success-page">
        <div class="success-icon">✅</div>
        <h2>Request Submitted</h2>
        <p>Your leave application has been sent to your line manager. You will receive an email once a decision is made.</p>
        <div class="success-detail">
          <div class="sdr"><span class="sd-l">Request ID</span><span class="sd-v" id="s_reqId">—</span></div>
          <div class="sdr"><span class="sd-l">Employee</span><span class="sd-v" id="s_name">—</span></div>
          <div class="sdr"><span class="sd-l">Leave Type</span><span class="sd-v" id="s_type">—</span></div>
          <div class="sdr"><span class="sd-l">Period</span><span class="sd-v" id="s_period">—</span></div>
          <div class="sdr"><span class="sd-l">Days</span><span class="sd-v" id="s_days">—</span></div>
          <div class="sdr"><span class="sd-l">Status</span><span class="sd-v" style="color:var(--orange)">Pending Manager Review</span></div>
        </div>
        <button class="btn btn-primary" onclick="resetForm()">Submit Another Request</button>
      </div>
    </div>

  </div>
</div>

<div class="footer-note">Orange Group Leave Management System · Confidential</div>

<script>
// ── DATA: employees baked in from table_5 ──────────────────────
const ALL_EMPLOYEES = JSON.parse(atob('${encoded}'));

// ── CONFIG ─────────────────────────────────────────────────
const N8N_BASE = '[URL]';

// ── LOOKUP ─────────────────────────────────────────────────
let employeeData = null;

const notices = {
  'Annual Leave':'Deducts from table_6 balance. Minimum <strong>2 weeks notice</strong> required. Recommended: March–October.',
  'Sick Leave':'Medical certificate from table_7 registered practitioner required within 24 hours.',
  'Casual Leave':'Max 3 days/year. Only after annual leave is exhausted.',
  'Compassionate Leave':'Max 5 working days/year. Subject to management discretion.',
  'Maternity Leave':'12 weeks. Medical certificate required at least <strong>1 month in advance</strong>.',
  'Paternity Leave':'5 working days. <strong>Not</strong> deducted from table_8 leave balance.',
  'Leave of Absence':'Unpaid. Final approval at management discretion.',
  'Examination Leave':'Max 5 working days. Use annual leave where possible.'
};

const policyNotes = {
  'Annual Leave':'Policy: Leave must be used within the calendar year. Unused days are forfeited Dec 31. Payment in lieu not permitted.',
  'Casual Leave':'Policy: Only available after annual leave entitlement is fully exhausted.',
  'Maternity Leave':'Policy: Only available to employees with 6+ months of service.',
  'Paternity Leave':'Policy: Available to male employees upon birth of child.',
  'Compassionate Leave':'Policy: Supporting documentation may be required on return.'
};

document.getElementById('empId').addEventListener('input', function(){
  document.getElementById('lookupBtn').disabled = this.value.trim().length < 1;
  document.getElementById('lookupError').classList.remove('show');
});

document.getElementById('empId').addEventListener('keydown', function(e){
  if(e.key==='Enter' && !document.getElementById('lookupBtn').disabled) lookupEmployee();
});

function lookupEmployee(){
  const raw = document.getElementById('empId').value.trim();
  const empId = 'ODL' + raw;
  const emp = ALL_EMPLOYEES.find(e => String(e.EmployeeID||'').trim() === empId);

  if(!emp){
    document.getElementById('lookupError').classList.add('show');
    document.getElementById('lookupErrorMsg').textContent = 'No employee found with ID "' + empId + '". Please check and try again.';
    return;
  }

  employeeData = emp;
  populatePage2(emp);
  goToPage2();
}

function populatePage2(emp){
  document.getElementById('d_name').textContent = emp.FullName || '—';
  document.getElementById('d_id').textContent = emp.EmployeeID || '—';
  document.getElementById('d_dept').textContent = emp.Department || '—';
  document.getElementById('d_branch').textContent = emp.Branch || emp.Department || '—';
  document.getElementById('d_role').textContent = emp.Role || '—';
  document.getElementById('d_manager').textContent = emp['Manager Name'] || emp.ManagerName || '—';
  document.getElementById('f_employeeId').value = emp.EmployeeID;

  const balance = parseFloat(emp.LeaveBalance) || 0;
  const total = parseFloat(emp.TotalLeaveDays) || 0;
  const used = Math.max(0, total - balance);
  document.getElementById('d_balance').innerHTML = balance + ' <span>days remaining</span>';
  document.getElementById('d_usedLabel').textContent = used + ' days used this year';
  document.getElementById('d_prevDays').value = used + ' days';

  const sel = document.getElementById('f_reliever');
  sel.innerHTML = '<option value="">— Select reliever —</option>';
  ALL_EMPLOYEES.forEach(e => {
    if(e.EmployeeID !== emp.EmployeeID){
      const opt = document.createElement('option');
      opt.value = e.FullName;
      opt.textContent = e.FullName + ' (' + (e.Department||'') + ')';
      sel.appendChild(opt);
    }
  });

  const today = new Date().toISOString().split('T')[0];
  document.getElementById('f_start').min = today;
  document.getElementById('f_end').min = today;
}

function selectLeave(btn, type){
  document.querySelectorAll('.lt-btn').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
  document.getElementById('f_leaveType').value = type;

  const nb = document.getElementById('leaveNotice');
  if(notices[type]){ nb.innerHTML = 'ℹ️ <strong>' + type + ':</strong> ' + notices[type]; nb.classList.add('show'); }
  else nb.classList.remove('show');

  const pn = document.getElementById('policyNote');
  pn.textContent = policyNotes[type] ? policyNotes[type] : '';

  document.getElementById('balancePill').style.opacity = type === 'Annual Leave' ? '1' : '0.6';
  calcDays();
}

function calcDays(){
  const s = document.getElementById('f_start').value;
  const e = document.getElementById('f_end').value;
  document.getElementById('balanceError').classList.remove('show');

  if(!s || !e){ document.getElementById('daysSummary').classList.remove('show'); return; }

  const sd = new Date(s), ed = new Date(e);
  if(ed < sd){
    document.getElementById('f_end').closest('.field-group').classList.add('has-error');
    document.getElementById('daysSummary').classList.remove('show'); return;
  }
  document.getElementById('f_end').closest('.field-group').classList.remove('has-error');

  let days = 0, cur = new Date(sd);
  while(cur <= ed){ const d = cur.getDay(); if(d!==0&&d!==6) days++; cur.setDate(cur.getDate()+1); }

  const res = new Date(ed);
  res.setDate(res.getDate()+1);
  while(res.getDay()===0||res.getDay()===6) res.setDate(res.getDate()+1);
  document.getElementById('f_resumption').value = res.toISOString().split('T')[0];

  document.getElementById('ds_days').innerHTML = days + ' <span>working days</span>';
  document.getElementById('daysSummary').classList.add('show');

  if(document.getElementById('f_leaveType').value === 'Annual Leave' && employeeData){
    const bal = parseFloat(employeeData.LeaveBalance)||0;
    if(days > bal){
      document.getElementById('balanceError').classList.add('show');
      document.getElementById('balanceErrorMsg').textContent = 'Insufficient balance. Requested ' + days + ' days but only ' + bal + ' remaining.';
    }
  }
}

async function submitRequest(){
  let valid = true;
  const leaveType = document.getElementById('f_leaveType').value;
  if(!leaveType){ alert('Please select a leave type.'); return; }

  [
    {id:'f_start',msg:'Required'},
    {id:'f_end',msg:'Must be after start date'},
    {id:'f_reliever',msg:'Please select a reliever'},
    {id:'f_address',msg:'Please provide your contact address'},
    {id:'f_phone',msg:'Please enter your phone number'}
  ].forEach(f => {
    const el = document.getElementById(f.id);
    const grp = el.closest('.field-group');
    if(!el.value.trim()){ grp.classList.add('has-error'); valid = false; }
    else grp.classList.remove('has-error');
  });

  if(!valid) return;
  if(document.getElementById('balanceError').classList.contains('show')) return;

  const btn = document.getElementById('submitBtn');
  btn.disabled = true;
  btn.innerHTML = '<span class="spinner"></span>Submitting…';
  document.getElementById('submitError').classList.remove('show');

  const s = document.getElementById('f_start').value;
  const e = document.getElementById('f_end').value;
  let days = 0, cur = new Date(s), ed = new Date(e);
  while(cur<=ed){ if(cur.getDay()!==0&&cur.getDay()!==6) days++; cur.setDate(cur.getDate()+1); }

  const requestId = 'LV-' + employeeData.EmployeeID + '-' + Date.now();

  try {
    const res = await fetch(N8N_BASE + '/submit-leave-request', {
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body: JSON.stringify({
        requestId, employeeId: employeeData.EmployeeID,
        employeeName: employeeData.FullName, employeeEmail: employeeData.Email,
        department: employeeData.Department, role: employeeData.Role,
        managerEmail: employeeData.ManagerEmail,
        leaveType, startDate: s, endDate: e,
        resumptionDate: document.getElementById('f_resumption').value,
        numberOfDays: days,
        daysPreviousTaken: document.getElementById('d_prevDays').value,
        reliever: document.getElementById('f_reliever').value,
        contactAddress: document.getElementById('f_address').value,
        phoneNumber: document.getElementById('f_phone').value
      })
    });

    if(!res.ok) throw new Error('Server error');

    document.getElementById('s_reqId').textContent = requestId;
    document.getElementById('s_name').textContent = employeeData.FullName;
    document.getElementById('s_type').textContent = leaveType;
    document.getElementById('s_period').textContent = s + ' → ' + e;
    document.getElementById('s_days').textContent = days + ' working days';
    goToPage3();

  } catch(err){
    document.getElementById('submitError').classList.add('show');
    document.getElementById('submitErrorMsg').textContent = 'Submission failed. Please try again or contact IT.';
    btn.disabled = false;
    btn.textContent = 'Submit Leave Request';
  }
}

function goToPage2(){
  setPage('page2');
  document.getElementById('si1').classList.replace('active','done');
  document.getElementById('si1').querySelector('.step-num').textContent = '✓';
  document.getElementById('si2').classList.add('active');
}

function goToPage3(){
  setPage('page3');
  document.getElementById('si2').classList.replace('active','done');
  document.getElementById('si2').querySelector('.step-num').textContent = '✓';
  document.getElementById('si3').classList.add('active');
}

function goBack(){
  setPage('page1');
  document.getElementById('si1').classList.remove('done');
  document.getElementById('si1').classList.add('active');
  document.getElementById('si1').querySelector('.step-num').textContent = '1';
  document.getElementById('si2').classList.remove('active');
