function setPage(id){
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById(id).classList.add('active');
  window.scrollTo(0,0);
}

function resetForm(){
  employeeData = null;
  document.getElementById('f_leaveType').value = '';
  document.querySelectorAll('.lt-btn').forEach(b => b.classList.remove('selected'));
  ['f_start','f_end','f_resumption','f_address','f_phone'].forEach(id => document.getElementById(id).value = '');
  document.getElementById('leaveNotice').classList.remove('show');
  document.getElementById('daysSummary').classList.remove('show');
  document.getElementById('balanceError').classList.remove('show');
  document.getElementById('si2').classList.remove('done','active');
  document.getElementById('si2').querySelector('.step-num').textContent = '2';
  document.getElementById('si3').classList.remove('active');
  document.getElementById('si3').querySelector('.step-num').textContent = '3';
  goBack();
}
